import json, pathlib, re
out = pathlib.Path("/home/user/Q-7/seo-audit/fixed-articles")

def wc(t): return len(re.findall(r"[A-Za-zÀ-ž؀-ۿ0-9]+", t))
def w(slug, title, seo, meta, kw, img, alt, inbound, html):
    data={"slug":slug,"title":title,"seo_title":seo,"meta_description":meta,"focus_keyword":kw,"featured_image":img,"featured_alt":alt,"inbound_suggestions":inbound,"content_html":html}
    (out/f"{slug}.json").write_text(json.dumps(data, ensure_ascii=False, indent=2), encoding='utf-8')
    print(f"wrote {slug} wc={wc(html)} seo={len(seo)} meta={len(meta)}")

